/**
 * Word membership for the `mustBeDictionaryWord` and `allowProperNouns` house rules.
 *
 * The word lists are NOT committed — they are generated by
 * `scripts/build-dictionary.mjs` from a public-domain source so we never vendor
 * licence-ambiguous data. When the generated files are missing the dictionary
 * reports itself unavailable and both rules degrade to "allow", rather than
 * rejecting every clue on a fresh checkout.
 */

export type Dictionary = {
  readonly available: boolean;
  readonly size: number;
  /** True for ordinary lowercase words. */
  has(word: string): boolean;
  /** True for words that only ever appear capitalised in the source list. */
  isProperNoun(word: string): boolean;
};

const UNAVAILABLE: Dictionary = {
  available: false,
  size: 0,
  has: () => true,
  isProperNoun: () => false,
};

const clean = (word: string) => word.trim().toLowerCase();

function toSet(words: Iterable<string>): Set<string> {
  const set = new Set<string>();
  for (const word of words) {
    const normalized = clean(word);
    if (normalized.length > 0) set.add(normalized);
  }
  return set;
}

export function createDictionary(
  commonWords: Iterable<string>,
  properNouns: Iterable<string> = [],
): Dictionary {
  const common = toSet(commonWords);
  const proper = toSet(properNouns);
  return {
    available: common.size > 0,
    size: common.size,
    has: (word) => common.has(clean(word)),
    isProperNoun: (word) => proper.has(clean(word)),
  };
}

export function unavailableDictionary(): Dictionary {
  return UNAVAILABLE;
}

/** Parse the newline-delimited format emitted by the build script. */
export function parseDictionary(common: string, proper = ''): Dictionary {
  return createDictionary(common.split('\n'), proper.split('\n'));
}
